                bar_rows.append((r,row[st],st,c-1))
            else: c+=1
    # vertical runs len>=2 -> stubs per column
    stubs={}
    for c in range(W):
        col=[g[r][c] for r in range(H)]; r=0
        while r<H:
            if col[r]!=0:
                st=r
                while r<H and col[r]==col[st]: r+=1
                if r-st>=2: stubs[c]=(col[st],st,r-1)
            else: r+=1
    for c in range(W):
        Rs=sorted([r for r,_,a,b in bar_rows if a<=c<=b])
        if not Rs: continue
        S=stubs.get(c,None)
        # bands between consecutive bar rows: color of lower bar
        for i in range(len(Rs)-1):
            lo,hi=Rs[i]+1,Rs[i+1]-1
            for rr in range(lo,hi+1):
                if out[rr][c]==0: out[rr][c]=bar_rows[next(x for x in bar_rows if x[0]==Rs[i+1])][1]
        # bottom band below last bar: stub color if stub, else unchanged
        if S is not None:
            for rr in range(Rs[-1]+1,H):
                if out[rr][c]==0: out[rr][c]=S[0]
        elif not any(True for _ in [0]):
            pass
    return out
