    H,W=len(g),len(g[0])
    out=[r[:] for r in g]
    # horizontal: fill gaps between consecutive runs with left run's color
    for r in range(H):
        row=g[r]; c=0
        while c<W:
            if row[c]!=0:
                st=c
                while c<W and row[c]==row[st]: c+=1
            else: c+=1
            # find next run start
            if c<W and row[c]!=0:
                st2=c
                while c<W and row[c]==row[st2]: c+=1
                for cc in range(st+1,st2):
                    if out[r][cc]==0: out[r][cc]=row[st]
    # vertical: sources = non-zero cells in column (after hpass); band below k-th source -> color of (k+1)-th source; below last -> stub color if stub exists
    for c in range(W):
        srcs=[(r,out[r][c]) for r in range(H) if out[r][c]!=0]
        if not srcs: continue
        stub=None
        colv=[g[r][c] for r in range(H)]
        r=0
        while r<H:
            if colv[r]!=0:
                st=r
                while r<H and colv[r]==colv[st]: r+=1
                if r-st>=2 and st>H-2: stub=(colv[st],r-1)  # only care if extends past last source
        # bands between consecutive sources: fill with lower source color
        for i in range(len(srcs)-1):
            lo,hi=srcs[i][0]+1,srcs[i+1][0]-1
            for rr in range(lo,hi+1):
                if out[rr][c]==0: out[rr][c]=srcs[i+1][1]
        # below last source: stub color if stub covers that range
        lo,hi=srcs[-1][0]+1,H-1
        if stub and hi>=stub[1]:
            for rr in range(lo,hi+1):
                if out[rr][c]==0: out[rr][c]=stub[0]
    return out
